{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is positive (e.g., >0.0) and model shows over-optimism, especially after recent spikes.",
    "Reduce forecast magnitude by 5-10% if sentiment is neutral or slightly negative and model shows persistent upward bias.",
    "Apply mean reversion correction if forecast deviates >15% from 14-day moving average of historical prices.",
    "Correct for lagged response: if true outcome is significantly higher than forecast, reduce forecast for next period by 3-5% to account for delayed market reaction.",
    "Avoid overshoot after sharp price spikes: if forecast exceeds true outcome by >10% in 3-5 consecutive days, apply downward pressure correction by 2-4% per day.",
    "Increase forecast sensitivity to sentiment when sentiment >0.3: model should align more closely with sentiment-driven price momentum."
  ]
}
